using System;
using System.Linq;
using CashflowChains.Economy;
namespace CashflowChains.City {
 public sealed class CityInvestmentQuote {public string Kind;public int PropertyId,X,Y,Seconds;public bool Unlocked,Affordable,BuilderAvailable;public long BeforeNet,AfterNet;public ItemAmount[] Costs,Owned;}
}
namespace CashflowChains.Empire {
 public sealed partial class EmpireEngine {
  public CashflowChains.City.CityInvestmentQuote QuoteCityInvestment(string kind,int x,int y,int propertyId=0){lock(gate){var actual=state.Copy();var a=ProjectNextCityDay(state.Copy());var city=RequiredCity(a);var d=config.City.Business(kind);var p=propertyId==0?null:city.Properties.Find(b=>b.Id==propertyId&&b.Kind==kind)??throw new ArgumentException("Unknown property");int target=p==null?1:p.Level+1;long factor=p==null?1:target;var costs=new[]{new ItemAmount("CASH",d.BuildCash*factor)}.Concat(d.BuildMaterials.Select(m=>new ItemAmount(m.ItemId,m.Quantity*factor))).ToArray();var reserved=actual.City.Trading==null?null:CashflowChains.City.CityDayModel.Forecast(config.City,actual.City.Trading);var owned=costs.Select(m=>{var r=reserved?.Resources.FirstOrDefault(i=>i.ItemId==m.ItemId);long held=r==null?0:Math.Max(0,r.Consumed+r.Exported+r.Spilled-r.Produced-r.Imported);return new ItemAmount(m.ItemId,Math.Max(0,actual.Economy.Amount(m.ItemId)-held));}).ToArray();var before=ForecastCity();foreach(var cost in costs){var balance=a.Economy.Balances.Find(b=>b.ItemId==cost.ItemId);if(balance!=null){balance.Earned=Math.Max(0,balance.Earned+balance.Purchased-cost.Quantity);balance.Purchased=0;}}if(p==null)city.Properties.Add(new CashflowChains.City.CityProperty{Id=city.NextPropertyId++,Kind=kind,X=x,Y=y,Level=1,Staff=d.BaseStaff});else p.Level++;var after=CashflowChains.City.CityDayModel.Forecast(config.City,OperatingPlan(config,a,Math.Max(1,a.Economy.LastTrustedAt)));return new CashflowChains.City.CityInvestmentQuote{Kind=kind,PropertyId=propertyId,X=x,Y=y,Seconds=propertyId!=0?d.BuildSeconds*target:city.Properties.Count<=3?Math.Min(d.BuildSeconds,city.Properties.Count==2?3:8):d.BuildSeconds,Unlocked=state.City.Day>=d.UnlockDay&&state.City.Population(config.City)>=d.UnlockPopulation,BuilderAvailable=state.City.Jobs.Count<state.City.BuilderSlots,Affordable=costs.All(m=>owned.Single(o=>o.ItemId==m.ItemId).Quantity>=m.Quantity),BeforeNet=before.Net,AfterNet=after.Net,Costs=costs,Owned=owned};}}
 }
}
